        return 0;
    }

    ArrayList<String> inverseStrings = new ArrayList<>();
    for (String string : strings) {
        inverseStrings.add(new StringBuilder(string).reverse().toString());
    }

    int maxLength = 0;
    for (String string : strings) {
        if (string.length() > maxLength) {
            maxLength = string.length();
        }
    }

    for (int length = maxLength; length >= 1; length--) {
        for (String string : strings) {
            if (string.length() < length) {
                continue;
            }

            if (string.contains(string.substring(0, length)) ||
                    inverseStrings.contains(inverseStrings.get(0, length))) {
                return length;
            }
        }
    }

    return 0;
}

