public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending coordinates are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n * n];

    // Initialize a queue to keep track of the n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    // Breadth-first search to visit all n-tersections
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        for (int[] path : paths) {
            int[] next = {current[0] + path[0], current[1] + path[1]};
            if (next[0] < 0 || next[0] >= n || next[1] < 0 || next[1] >= n) {
                continue;
            }
            if (next[0] == end[0] && next[1] == end[1]) {
                return "can be travelled";
            }
            if (!visited[next[0] * n + next[1]]) {
                visited[next[0] * n + next[1]] = true;
                queue.offer(next);
            }
        }
    }

    // Return "cannot be travelled" if the ending n-tersection is not reached
    return "cannot be travelled";
}

