public boolean canArrange(int[] arr, int k) {
    // Initialize the result, the number of pairs, and the pair index
    boolean result = false;
    int pairCount = arr.length / 2;
    int pairIndex = 0;

    // Iterate over the array
    for (int i = 0; i < arr.length; i++) {
        // If the current element is divisible by k, add it to the current pair
        if (arr[i] % k == 0) {
            pairCount--;
            pairIndex = i;
            continue;
        }

        // If the current pair is full, reset the pair index
        if (pairIndex + 1 == i) {
            pairIndex = 0;
        }

        // If all pairs have been processed, set the result to true
        if (pairCount == 0) {
            result = true;
            break;
        }
    }

    // Return the result
    return result;
}

